/**
 * Resolver that finds the exact Industrial Training Mission for any topic key or ID.
 */
export function getIndustrialTrainingMission(
  topicKeyOrId: string | number | undefined,
  fallbackMission?: RealLifeMission,
  topicTitle?: string,
  isExcelTrack?: boolean
): IndustrialMissionConfig {
  const strKey = String(topicKeyOrId || '1.1');
  if (PROJECTS_TRAINING_MISSIONS[strKey]) {
    return PROJECTS_TRAINING_MISSIONS[strKey];
  }
  if (INSIGHTS_TRAINING_MISSIONS[strKey]) {
    return INSIGHTS_TRAINING_MISSIONS[strKey];
  }
  if (GENAI_TRAINING_MISSIONS[strKey]) {
    return GENAI_TRAINING_MISSIONS[strKey];
  }
  if (POWERBI_TRAINING_MISSIONS[strKey]) {
    return POWERBI_TRAINING_MISSIONS[strKey];
  }
  if (SQL_TRAINING_MISSIONS[strKey]) {
    return SQL_TRAINING_MISSIONS[strKey];
  }
  if (EXCEL_TRAINING_MISSIONS[strKey]) {
    return EXCEL_TRAINING_MISSIONS[strKey];
  }
  if (INDUSTRIAL_TRAINING_MISSIONS[strKey]) {
    return INDUSTRIAL_TRAINING_MISSIONS[strKey];
  }

  const numeric = Number(topicKeyOrId);
  if (!isNaN(numeric)) {
    if (PROJECTS_TRAINING_MISSIONS_BY_ID[numeric]) {
      return PROJECTS_TRAINING_MISSIONS_BY_ID[numeric];
    }
    if (INSIGHTS_TRAINING_MISSIONS_BY_ID[numeric]) {
      return INSIGHTS_TRAINING_MISSIONS_BY_ID[numeric];
    }
    if (GENAI_TRAINING_MISSIONS_BY_ID[numeric]) {
      return GENAI_TRAINING_MISSIONS_BY_ID[numeric];
    }
    if (POWERBI_TRAINING_MISSIONS_BY_ID[numeric]) {
      return POWERBI_TRAINING_MISSIONS_BY_ID[numeric];
    }
    if (SQL_TRAINING_MISSIONS_BY_ID[numeric]) {
      return SQL_TRAINING_MISSIONS_BY_ID[numeric];
    }
    if (isExcelTrack && EXCEL_TRAINING_MISSIONS_BY_ID[numeric]) {
      return EXCEL_TRAINING_MISSIONS_BY_ID[numeric];
    }
    if (
      EXCEL_TRAINING_MISSIONS_BY_ID[numeric] &&
      numeric >= 27 &&
      numeric <= 76 &&
      (isExcelTrack || (typeof window !== 'undefined' && window.location.hash.includes('tab=3')))
    ) {
      return EXCEL_TRAINING_MISSIONS_BY_ID[numeric];
    }
    if (INDUSTRIAL_TRAINING_MISSIONS_BY_ID[numeric]) {
      return INDUSTRIAL_TRAINING_MISSIONS_BY_ID[numeric];
    }
    if (EXCEL_TRAINING_MISSIONS_BY_ID[numeric]) {
      return EXCEL_TRAINING_MISSIONS_BY_ID[numeric];
    }
  }

  const normalizedKey = strKey.includes('.') ? strKey : `1.${strKey}`;
  if (PROJECTS_TRAINING_MISSIONS[normalizedKey]) {
    return PROJECTS_TRAINING_MISSIONS[normalizedKey];
  }
  if (INSIGHTS_TRAINING_MISSIONS[normalizedKey]) {
    return INSIGHTS_TRAINING_MISSIONS[normalizedKey];
  }
  if (GENAI_TRAINING_MISSIONS[normalizedKey]) {
    return GENAI_TRAINING_MISSIONS[normalizedKey];
  }
  if (POWERBI_TRAINING_MISSIONS[normalizedKey]) {
    return POWERBI_TRAINING_MISSIONS[normalizedKey];
  }
  if (SQL_TRAINING_MISSIONS[normalizedKey]) {
    return SQL_TRAINING_MISSIONS[normalizedKey];
  }
  if (EXCEL_TRAINING_MISSIONS[normalizedKey]) {
    return EXCEL_TRAINING_MISSIONS[normalizedKey];
  }
  if (INDUSTRIAL_TRAINING_MISSIONS[normalizedKey]) {
    return INDUSTRIAL_TRAINING_MISSIONS[normalizedKey];
  }

  // Dynamic fallback for any advanced/custom topic in Tab 3-8
  const safeTitle = fallbackMission?.title?.replace(/^Mission:\s*/i, '') || topicTitle || 'Industrial Business Case';
  const safeScenario = fallbackMission?.scenario || 'Analyze operational data to identify bottlenecks and make an informed decision.';
  const safePrompt = fallbackMission?.prompt || 'Examine the key records and formulate the optimal decision.';
  const safeExpected = fallbackMission?.expectedResponse || 'Examine primary operational records to discover useful insights.';

  return {
    id: `it-dynamic-${strKey}`,
    moduleName: ACTIVITY_LABELS.realWorldChallenge.fallbackModuleName,
    topicNumber: 1,
    topicKey: strKey,
    topicTitle: topicTitle || safeTitle,
    difficulty: 'Level 0',
    missionTitle: safeTitle.startsWith('Help') || safeTitle.startsWith('Fix') ? safeTitle : `Optimize: ${safeTitle}`,
    persona: 'analyst',
    personaName: 'Aditi Roy',
    personaRole: 'Lead Analytics Consultant',
    situation: safeScenario,
    task: safePrompt,
    options: [
      {
        id: `opt-dyn-a`,
        letter: 'A',
        title: 'Operational Transaction Records',
        subtitle: 'Core records directly tracking the business activity',
        iconType: 'bar-chart',
        isCorrect: true,
      },
      {
        id: `opt-dyn-b`,
        letter: 'B',
        title: 'Cosmetic Wall Paint & Decor',
        subtitle: 'Visual appearance without operational figures',
        iconType: 'palette',
        isCorrect: false,
      },
      {
        id: `opt-dyn-c`,
        letter: 'C',
        title: 'Unrelated Personal Hobby',
        subtitle: 'Irrelevant external opinions with zero data correlation',
        iconType: 'movie',
        isCorrect: false,
      },
    ],
    correctExplanation: safeExpected,
    whyThisWorks: 'Practical business problem-solving requires examining evidence from verified records.',
    mentorHint: 'Think about whether this problem requires operational data or cosmetic guesses.',
    chartType: 'declining-shop',
    learningOutcomes: [
      'Understand the business problem',
      'Select the right data source',
      'Discover actionable insights from trends',
      'Make evidence-based decisions',
    ],
  };
}
